  for k in range(1,len(chunks),2):
   outer=int(chunks[k]);samples=re.findall(r'Solving for (p|Ux|Uy|Uz), Initial residual = ('+number+r'), Final residual = ('+number+r'), No Iterations (\d+)',chunks[k+1],re.I);require(all(any(q[0]==n for q in samples) for n in ('p','Ux','Uy')),'Every actual outer pressure/component solve')
